fn io()->MediaFlowIO<String,()> {MediaFlowIO{form:Some(Arc::new(ByteFormData{values:Default::default()})),form_policy:form_policy(),on_form_error:Arc::new(|e|format!("{e:?}")),write_error:None,write_patch:Some(Arc::new(|_,_,_,_|effect_sync!{body:||effect_server::reply!{text("patch".to_owned())}})),write_patches:Some(Arc::new(|_,_|effect_sync!{body:||effect_server::reply!{text("patches".to_owned())}})),write_html_status:Some(Arc::new(|_,_,_|effect_sync!{body:||effect_server::reply!{text("html".to_owned())}})),write_html:None}}
#[test]fn inline_create_retains_shared_input_identity_through_validation_creation_and_error_render(){
 for reject in [false,true]{let input=Arc::new(Mutex::new("parsed"));let parsed=input.clone();let validate=input.clone();let create=input.clone();let render=input.clone();let rendered=Arc::new(Mutex::new(Vec::new()));let output=rendered.clone();let created=Arc::new(AtomicUsize::new(0));let calls=created.clone();
 let options=MediaInlineCreateFlowOptions{io:io(),bad_request_message:"bad".into(),internal_error_message:"create failed".into(),surface:None,normalize_role:None,role_options:MediaAttachmentRoleOptions::default(),current_inputs:Some(Arc::new(|_,_,_|effect_sync!{body:||Vec::new()})),preview_items:Some(Arc::new(|_,_|effect_sync!{body:||Vec::new()})),build_manager:Some(Arc::new(|_,_,_,_|None)),render_manager:Some(Arc::new(|_|maud::Markup::default())),default_role:None,parse_input:Some(Arc::new(move|_,_|parsed.clone())),validate_input:Some(Arc::new(move|_,value:&Arc<Mutex<&str>>|{assert!(Arc::ptr_eq(value,&validate));*value.lock().unwrap()="validated";if reject{"invalid"}else{""}.into()})),create_asset:Some(Arc::new(move|_,value:Arc<Mutex<&str>>|{assert!(Arc::ptr_eq(&value,&create));assert_eq!(*value.lock().unwrap(),"validated");*value.lock().unwrap()="created";calls.fetch_add(1,Ordering::SeqCst);effect_try_sync!{body:||Err::<InputBytes,String>("failed".into()),on_error:std::convert::identity}})),render_create:Some(Arc::new(move|_,_,value:Arc<Mutex<&str>>,error,_|{assert!(Arc::ptr_eq(&value,&render));output.lock().unwrap().push((*value.lock().unwrap(),error));MediaInlineCreateRender{root_id:"create".into(),component:maud::Markup::default()}}))};
 let _reply=success(handle_media_inline_create(&request("/"),options),Arc::new(()));assert_eq!(created.load(Ordering::SeqCst),usize::from(!reject));let output=rendered.lock().unwrap();assert_eq!(output.len(),1);assert_eq!(output[0].0,if reject{"validated"}else{"created"});assert_eq!(output[0].1,if reject{"invalid"}else{"create failed"});
 }
}
#[test]fn picker_native_request_redirects_without_touching_builder(){let calls=Arc::new(AtomicUsize::new(0));let c=calls.clone();let options=MediaPickerSearchFlowOptions{io:io(),bad_request_message:"bad".into(),internal_error_message:"internal".into(),page_size:2,redirect_path:"/media".into(),build_page:Some(Arc::new(move|_,_,_,_|{c.fetch_add(1,Ordering::SeqCst);effect_sync!{body:||MediaPickerPageVM::default()}})),render_picker:None};let _reply=success(handle_media_picker_search(&request("/picker"),options),Arc::new(()));assert_eq!(calls.load(Ordering::SeqCst),0);}
#[test]fn picker_second_page_preserves_query_and_resolved_path_in_datastar_patch(){
 let observed=Arc::new(Mutex::new(Vec::new()));let state=observed.clone();let mut policy=io();let patch=observed.clone();policy.write_patch=Some(Arc::new(move|_,root,mode,html|{patch.lock().unwrap().push(format!("{}|{mode}|{}",String::from_utf8_lossy(root.as_bytes()),html.into_string()));effect_sync!{body:||effect_server::reply!{text("done".to_owned())}}}));
 let options=MediaPickerSearchFlowOptions{io:policy,bad_request_message:"bad".into(),internal_error_message:"error".into(),page_size:2,redirect_path:"/media".into(),build_page:Some(Arc::new(move|_,query,_,_|{assert_eq!((query.limit,query.offset),(2,2));assert_eq!(query.search.as_bytes(),b"image");state.lock().unwrap().push("built".into());effect_sync!{body:||MediaPickerPageVM{root_id:"picker-root".into(),items:vec![MediaPickerItemVM{id:"path".into(),resolved_preview:"/cdn/path.jpg".into(),..Default::default()}],..Default::default()}}})),render_picker:Some(Arc::new(|p|maud::html!{img src=(&p.items[0].resolved_preview);}))};
 let req=effect_server::Request::from_native(http::Request::builder().uri("/picker?page=2&search=image").header("datastar-request","true").body(effect_server::native::axum::body::Body::empty()).unwrap(),effect::Cancellation::new());let _reply=success(handle_media_picker_search(&req,options),Arc::new(()));let rows=observed.lock().unwrap();assert_eq!(rows.len(),2);assert_eq!(rows[0],"built");assert!(rows[1].starts_with("picker-root|inner|"));assert!(rows[1].contains("/cdn/path.jpg"));
}
struct DeleteStore{reads:Arc<AtomicUsize>,deleted:Arc<Mutex<Vec<InputBytes>>>,failure:Arc<str>,duration:Option<Arc<std::sync::atomic::AtomicI64>>}
impl MediaAssetStore<Arc<str>,()> for DeleteStore{
 fn get_by_id(&self,_:InputBytes)->Effect<Option<MediaAssetRecord>,Arc<str>,()>{let reads=self.reads.clone();effect_sync!{body:move||{reads.fetch_add(1,Ordering::SeqCst);None}}}
 fn get_by_ids(&self,_:Vec<InputBytes>)->Effect<BTreeMap<InputBytes,MediaAssetRecord>,Arc<str>,()>{effect_sync!{body:||BTreeMap::new()}}
 fn list(&self,_:MediaQuery)->Effect<Option<MediaAssetListResult>,Arc<str>,()>{effect_sync!{body:||None}}
 fn create(&self,record:AtomicRef<MediaAssetRecord>)->Effect<(),Arc<str>,()>{let duration=self.duration.clone();effect_ref!{in_place;reference:record,modify:move|record|{if let Some(expected)=duration.as_ref(){let stored=record.duration.as_ref().expect("duration retained");assert!(Arc::ptr_eq(stored,expected));stored.store(18,Ordering::SeqCst);}record.id="consumer-assigned".into();},}}
 fn update(&self,_:AtomicRef<MediaAssetRecord>)->Effect<(),Arc<str>,()>{effect_sync!{body:||()}}
 fn delete(&self,id:InputBytes)->Effect<(),Arc<str>,()>{let output=self.deleted.clone();let error=self.failure.clone();effect_try_sync!{once;body:move||{output.lock().unwrap().push(id);Err::<(),_>(error)},on_error:std::convert::identity}}
}
#[test]fn direct_media_delete_skips_read_and_preserves_store_error_identity(){
 let reads=Arc::new(AtomicUsize::new(0));let deleted=Arc::new(Mutex::new(Vec::new()));let failure:Arc<str>="delete failed".into();let runtime=new_media_asset_store_runtime(MediaAssetStoreRuntimeOptions{assets:Some(Arc::new(DeleteStore{reads:reads.clone(),deleted:deleted.clone(),failure:failure.clone(),duration:None})),..Default::default()});
 let options=MediaAssetCommandBindingOptions{runtime,kind:effect_cms::definitions::ResourceKind::new("media"),redirect_route:String::new(),invalid_request_error:Arc::new(|message|message.to_owned().into()),form:None,form_policy:form_policy()};
 let execute=media_asset_delete_executor(options);let input=CommandInput{detail_query:effect_cms::queries::ResourceDetailQuery{id:" id ".into(),..Default::default()},..Default::default()};let outcome=block_on(execute(&request("/"),AtomicRef::new(input)).run(Arc::new(())));match outcome{Exit::Fail(error)=>assert!(Arc::ptr_eq(&error,&failure)),_=>panic!("expected direct store error")};assert_eq!(reads.load(Ordering::SeqCst),0);assert_eq!(deleted.lock().unwrap()[0].as_bytes(),b"id");
}
#[test]fn media_dashboard_row_and_page_urls_use_localized_action_and_provider_metadata(){
 let edit:MediaDashboardRecordHref=Arc::new(|r|format!("/fr/media/{}/edit",r.id));let delete:MediaDashboardRecordHref=Arc::new(|r|format!("/fr/media/{}/delete",r.id));let row=media_dashboard_row(None,&MediaAssetRecord{id:"asset-1".into(),kind:"image".into(),status:"ready".into(),title:"Image".into(),provider:"cdn".into(),..Default::default()},None,None,None,Some(&edit),Some(&delete));assert_eq!(row.title,"Image");assert_eq!(row.title_href,"/fr/media/asset-1/edit");assert!(row.meta_text.contains("cdn"));let actions=row.actions.as_ref().unwrap().with(|a|a.to_vec());assert_eq!(actions.len(),2);assert_eq!(actions[1].href,"/fr/media/asset-1/delete");let href=media_dashboard_page_href(Some(&request("/en/media?search=hello&status=ready")),"/fr/media","page",2);assert!(href.starts_with("/fr/media?"));assert!(href.contains("search=hello"));assert!(href.contains("page=2"));
}
#[test]fn media_form_frame_override_precedes_store_backed_attachment_loader(){
 use effect_cms::{forms::FormPageSource,definitions::{ResourceKind,ResourceViewMode},validation::ValidationResult};
 for override_items in [false,true]{let calls=Arc::new(AtomicUsize::new(0));let count=calls.clone();let options=ResourceMediaFormFrameOptions{forms:FormPageSource::<(),String,()>::default(),context:Arc::new(()),kind:ResourceKind::new("article"),mode:ResourceViewMode::new("new"),error_message:String::new(),validation:ValidationResult::default(),fallback_content_id:Some("owner".into()),owner_type:"article".into(),runtime:MediaAssetStoreRuntime::<String,()>::default(),attachments_override:override_items.then(||vec![MediaAttachmentFormItem{asset_id:"override".into(),..Default::default()}]),load_attachments:Some(Arc::new(move|_,owner,id|{assert_eq!(owner.as_bytes(),b"article");assert_eq!(id.as_bytes(),b"owner");count.fetch_add(1,Ordering::SeqCst);effect_sync!{body:||vec![MediaAttachmentFormItem{asset_id:"stored".into(),..Default::default()}]}})),form:Some(Arc::new(ByteFormData{values:Default::default()})),form_policy:form_policy(),on_form_error:Arc::new(|e|format!("{e:?}"))};let frame=success(build_resource_media_form_frame(&request("/"),options),Arc::new(()));assert_eq!(frame.content_id.as_bytes(),b"owner");assert_eq!(calls.load(Ordering::SeqCst),usize::from(!override_items));assert_eq!(frame.attachments[0].asset_id.as_bytes(),if override_items{b"override".as_slice()}else{b"stored".as_slice()});}
}
#[test]fn create_store_mutation_retains_duration_alias_and_returns_store_assigned_identity(){
 let duration=Arc::new(std::sync::atomic::AtomicI64::new(12));let runtime=new_media_asset_store_runtime(MediaAssetStoreRuntimeOptions{assets:Some(Arc::new(DeleteStore{reads:Arc::new(AtomicUsize::new(0)),deleted:Arc::new(Mutex::new(Vec::new())),failure:"unused".into(),duration:Some(duration.clone())})),new_id:Some(Arc::new(||"prepared".into())),now_unix:Some(Arc::new(||99)),..Default::default()});
 let program=runtime.create_asset_from_form(&request("/"),MediaAssetFormInput{kind:"image".into(),source_kind:"remote".into(),status:"ready".into(),duration:Some(duration.clone()),..Default::default()});assert_eq!(duration.load(Ordering::SeqCst),12);assert_eq!(success(program,Arc::new(())),"consumer-assigned");assert_eq!(duration.load(Ordering::SeqCst),18);
}
